from pathlib import Path
p=Path("backend/app/activities/repository.py")
raw=p.read_bytes(); bom=b"\xef\xbb\xbf" if raw.startswith(b"\xef\xbb\xbf") else b""
s=raw[len(bom):].decode("utf-8").replace("\r\n","\n")
def rep(a,b):
    global s
    if s.count(a)!=1: raise RuntimeError(f"expected once, found {s.count(a)}: {a[:90]!r}")
    s=s.replace(a,b,1)
rep("_MAX_WINDOW_SECONDS = 3_600\n", "_MAX_WINDOW_SECONDS = 3_600\n_MAX_WINDOWS_SESSION_ID = 4_294_967_295\n")
rep("    dispatch_closed: bool\n\n\n@dataclass(frozen=True)\nclass SourceSnapshot:", "    dispatch_closed: bool\n    running_owner_session_id: int | None = None\n    lease_recoverable: bool = False\n    sources_valid: bool = False\n\n\n@dataclass(frozen=True)\nclass SourceSnapshot:")
rep("    window_seconds: int\n\n\n@dataclass(frozen=True)\nclass UnresolvedOperation:", "    window_seconds: int\n    running_owner_session_id: int | None = None\n\n\n@dataclass(frozen=True)\nclass UnresolvedOperation:")
rep("        window_seconds: int,\n    ) -> ActivityLease | None:", "        window_seconds: int,\n        running_owner_session_id: int | None = None,\n        expected_previous_generation: int | None = None,\n    ) -> ActivityLease | None:")
rep("        过期 running 租约按既有接续规则处理：", "        低层缺省 NULL 仅供合成调用兼容，不授予旧 Job 自动恢复资格；\n        生产 SUP 必须提供自身 Windows 会话号并先完成旧树核查。\n        过期 running 租约按既有接续规则处理：")
rep('            raise ValueError("时间窗口必须在 1 到 3600 秒之间")\n\n        async def operation(connection: object) -> ActivityLease | None:', '            raise ValueError("时间窗口必须在 1 到 3600 秒之间")\n        if running_owner_session_id is not None and (\n            type(running_owner_session_id) is not int\n            or not 0 <= running_owner_session_id <= _MAX_WINDOWS_SESSION_ID\n        ):\n            raise ValueError("Windows 会话号必须在 DWORD 域内")\n        if expected_previous_generation is not None and (\n            type(expected_previous_generation) is not int or expected_previous_generation < 0\n        ):\n            raise ValueError("旧执行代次必须是非负整数")\n\n        async def operation(connection: object) -> ActivityLease | None:')
rep('            if row is None or not sources_valid:\n                raise ActivityLedgerConflict("活动或来源快照不可用")\n            if row["status"] == "cancelled"', '            if row is None or not sources_valid:\n                raise ActivityLedgerConflict("活动或来源快照不可用")\n            if expected_previous_generation is not None and (\n                row["status"] != "running"\n                or row["execution_generation"] != expected_previous_generation\n                or row["running_owner_session_id"] != running_owner_session_id\n            ):\n                raise ActivityLedgerConflict("已核查旧代次或会话身份已变化")\n            if row["status"] == "cancelled"')
rep("                                  executor_id = NULL, lease_expires_at = NULL,\n                                  dispatch_closed = TRUE,", "                                  executor_id = NULL, lease_expires_at = NULL,\n                                  running_owner_session_id = NULL,\n                                  dispatch_closed = TRUE,")
rep("                          lease_expires_at = %s, running_reserved_seconds = %s,\n                          dispatch_closed = FALSE,", "                          lease_expires_at = %s, running_reserved_seconds = %s,\n                          running_owner_session_id = %s,\n                          dispatch_closed = FALSE,")
rep("                (executor_id, generation, lease_expires_at, effective_window, settled, activity_id),", "                (executor_id, generation, lease_expires_at, effective_window,\n                 running_owner_session_id, settled, activity_id),")
rep("                effective_window,\n            )", "                effective_window,\n                running_owner_session_id,\n            )")
rep('        """恢复入口的只读快照；调用方须持活动排他锁并在 claim 前核对旧 Job。"""', '        """恢复入口短事务快照；来源锁沿用 claim 顺序，调用方须持活动互斥。"""')
rep('        async def operation(connection: object) -> WindowSnapshot:\n            cursor = await connection.execute(\n                """SELECT status, execution_generation, running_reserved_seconds, dispatch_closed\n                     FROM activities WHERE id = %s""",', '        async def operation(connection: object) -> WindowSnapshot:\n            snapshots = await self._source_rows(connection, activity_id)\n            sources_valid = bool(snapshots) and await self._lock_sources(connection, snapshots)\n            cursor = await connection.execute(\n                """SELECT status, execution_generation, running_reserved_seconds, dispatch_closed,\n                          running_owner_session_id,\n                          (lease_expires_at IS NULL OR lease_expires_at <= CURRENT_TIMESTAMP)\n                              AS lease_recoverable,\n                          (deadline_at > CURRENT_TIMESTAMP) AS deadline_live\n                     FROM activities WHERE id = %s""",')
rep('                row["running_reserved_seconds"], row["dispatch_closed"],\n            )', '                row["running_reserved_seconds"], row["dispatch_closed"],\n                row["running_owner_session_id"],\n                bool(row["lease_recoverable"] and row["deadline_live"]),\n                sources_valid,\n            )')
rep("                          executor_id = NULL, lease_expires_at = NULL,\n                          running_reserved_seconds = 0,", "                          executor_id = NULL, lease_expires_at = NULL,\n                          running_owner_session_id = NULL,\n                          running_reserved_seconds = 0,")
rep("                          lease_expires_at = NULL, cancelled_at = CURRENT_TIMESTAMP,\n                          dispatch_closed = TRUE,", "                          lease_expires_at = NULL, cancelled_at = CURRENT_TIMESTAMP,\n                          running_owner_session_id = NULL,\n                          dispatch_closed = TRUE,")
p.write_bytes(bom+s.replace("\n","\r\n").encode("utf-8") if b"\r\n" in raw else bom+s.encode("utf-8"))
